/* Penny prototype UI layer: routing with context, sheets with focus trap, generic form engine, toasts, notifications, lock screen, boot. */
(function(PO){
const $ = s => document.querySelector(s);
const esc = s => String(s==null?'':s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
PO.esc = esc; PO.$ = $;
PO.ui = { screen:'home', params:{}, stack:[], sheets:[], sel:new Set(), tablet:false, locked:false, lastActive:Date.now(), pane:'notes' };
PO.SCREENS = {}; PO.SHEETS = {}; PO.ACT = {}; PO.NOTES = {};

/* ---------- routing: hash carries screen and context */
const encodeHash = (s,p) => '#'+s+(Object.keys(p||{}).length?'?'+Object.entries(p).map(([k,v])=>`${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&'):'');
const decodeHash = () => { const h=location.hash.slice(1); if(!h) return null; const [s,q]=h.split('?'); const p={}; (q||'').split('&').filter(Boolean).forEach(kv=>{ const [k,v]=kv.split('='); p[decodeURIComponent(k)]=decodeURIComponent(v||''); }); return {screen:s, params:p}; };
PO.go = (screen, params={}, o={}) => { if(!PO.SCREENS[screen]) screen='home'; if(!o.replace && !(PO.ui.screen===screen && JSON.stringify(PO.ui.params)===JSON.stringify(params))) PO.ui.stack.push({screen:PO.ui.screen, params:PO.ui.params}); if(PO.ui.stack.length>30) PO.ui.stack.shift(); PO.ui.screen=screen; PO.ui.params=params; PO.ui.sel.clear(); PO.closeAllSheets(); try{ history.replaceState(null,'',encodeHash(screen,params)); }catch(e){} PO.render(); const sc=$('#screen'); if(sc){ sc.scrollTop=0; } PO.announce((PO.NOTES[screen]||{}).t||screen); };
PO.back = () => { const prev=PO.ui.stack.pop(); if(prev) PO.go(prev.screen, prev.params, {replace:true}); else PO.go('home',{},{replace:true}); };
window.addEventListener('hashchange', ()=>{ const r=decodeHash(); if(r && PO.SCREENS[r.screen] && (r.screen!==PO.ui.screen || JSON.stringify(r.params)!==JSON.stringify(PO.ui.params))) PO.go(r.screen, r.params, {replace:true}); });

/* ---------- render */
PO.render = () => { if(!PO.state) return; if(PO.ui.locked) return; const inner=$('#inner'); inner.dir = PO.isRTL()?'rtl':'ltr'; inner.lang=PO.state.settings.lang; const th=PO.state.settings.theme; inner.dataset.appTheme = th==='system'?'':th; inner.dataset.text=PO.state.settings.text||'normal';
  const scr=PO.SCREENS[PO.ui.screen]||PO.SCREENS.home; let html; try{ html=scr.render(PO.ui.params); }catch(e){ console.error(e); html=`<div class="card err"><b>This screen hit an error.</b><div class="sub">${esc(e.message)}</div><div style="height:8px"></div><button class="btn sm ghost" data-go="home">Go home</button></div>`; }
  const sc=$('#screen'); sc.innerHTML=html; sc.classList.toggle('two', !!(scr.two && PO.ui.tablet)); if(scr.after) try{ scr.after(PO.ui.params); }catch(e){ console.error(e); }
  const onboarding = PO.ui.screen==='onboarding'; $('#tabbar').style.visibility=onboarding?'hidden':'visible'; $('#fab').hidden=onboarding;
  $('#tabbar').innerHTML = [['home',PO.t('home'),'M3 11l9-7 9 7v9a1 1 0 0 1-1 1h-5v-6h-6v6H4a1 1 0 0 1-1-1z'],['budgets',PO.t('budgets'),'M3 5h18v14H3zM3 10h18M8 15h3'],null,['people',PO.t('people'),'M9 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM17 12.5a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5zM3 19c0-3 3-5 6-5s6 2 6 5M14 18c0-2 1.5-3.5 3.5-3.5S21 16 21 18'],['insights',PO.t('insights'),'M4 19V9M10 19V5M16 19v-8M22 19H2']].map(t=>t?`<button data-go="${t[0]}" aria-current="${tabFor(PO.ui.screen)===t[0]?'page':'false'}"><svg viewBox="0 0 24 24"><path d="${t[2]}"/></svg>${esc(t[1])}</button>`:'<span></span>').join('');
  $('#syncState').textContent = PO.decoy ? 'Decoy book' : (PO.saveState==='error' ? 'Local · not saved (storage blocked)' : PO.saveState==='pending' ? 'Local · saving…' : (PO.state.settings.lockPin?'Local · encrypted':'Local · saved'));
  renderNotes(); PO.ui.sheets.forEach((s,i)=>renderSheet(i)); };
const tabFor = s => ({home:'home',review:'home',alerts:'home',history:'home',trash:'home',budgets:'budgets',envelope:'budgets',goals:'budgets',people:'people',person:'people',group:'people',remittances:'people',circles:'people',circle:'people',insights:'insights',recurring:'insights',debt:'insights',transactions:'insights'})[s]||'';
PO.onChange(()=>{ const el=$('#syncState'); if(el && PO.state && !PO.ui.locked) el.textContent = PO.decoy ? 'Decoy book' : (PO.saveState==='error' ? 'Local · not saved (storage blocked)' : (PO.state.settings.lockPin?'Local · encrypted':'Local · saved')); });

/* ---------- notes and gap panel */
function renderNotes(){ const key = PO.ui.sheets.length ? (PO.ui.sheets[PO.ui.sheets.length-1].kind) : PO.ui.screen; const n=PO.NOTES[key]||PO.NOTES[PO.ui.screen]||{t:key,tag:'',job:'',pts:[]}; $('#nTitle').innerHTML=`${esc(n.t)} ${n.tag?`<span class="pill acc">${esc(n.tag)}</span>`:''}`; $('#nJob').textContent=n.job||''; $('#nList').innerHTML=(n.pts||[]).map(p=>`<li>${esc(p)}</li>`).join('');
  $('#navgrid').innerHTML=Object.keys(PO.NOTES).filter(k=>PO.SCREENS[k]||PO.SHEETS[k]).map(k=>`<button data-nav="${k}" aria-current="${key===k}">${esc(PO.NOTES[k].t)}</button>`).join(''); }
PO.renderGaps = () => { $('#gapsTable').innerHTML = `<table>${PO.GAPS.map(([n,text,screen,params])=>`<tr><td>${n}</td><td>${esc(text)}</td><td><button data-gap="${screen}" data-p='${esc(JSON.stringify(params||{}))}'>Show</button></td></tr>`).join('')}</table>`; };

/* ---------- sheets with focus trap */
const FOCUSABLE='button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])';
PO.openSheet = (kind, data={}) => { if(PO.ui.sheets.length>=2) PO.ui.sheets.pop(); PO.ui.sheets.push({kind, data, returnFocus:document.activeElement}); renderSheet(PO.ui.sheets.length-1); renderNotes(); };
PO.closeSheet = (idx) => { const i = idx==null ? PO.ui.sheets.length-1 : idx; const s=PO.ui.sheets[i]; if(!s) return; PO.ui.sheets.splice(i,1); const el = $(i===0?'#sheet':'#sheet2'); el.hidden=true; el.innerHTML=''; $(i===0?'#scrim':'#scrim2').hidden=true; if(i===0 && PO.ui.sheets.length){ const moved=PO.ui.sheets[0]; $('#sheet2').hidden=true; $('#scrim2').hidden=true; renderSheet(0); } try{ s.returnFocus && s.returnFocus.focus && s.returnFocus.focus(); }catch(e){} renderNotes(); };
PO.closeAllSheets = () => { while(PO.ui.sheets.length) PO.closeSheet(); };
PO.rerenderSheet = () => { PO.ui.sheets.forEach((s,i)=>renderSheet(i)); };
function renderSheet(i){ const s=PO.ui.sheets[i]; if(!s) return; const el=$(i===0?'#sheet':'#sheet2'); const scrim=$(i===0?'#scrim':'#scrim2'); const def=PO.SHEETS[s.kind]; if(!def){ el.hidden=true; return; } el.innerHTML = `<div class="grab"></div>` + def.render(s.data, s); el.hidden=false; scrim.hidden=false; el.setAttribute('aria-label', def.label||s.kind); if(def.after) try{ def.after(s.data, s); }catch(e){ console.error(e); } if(!s.focused){ s.focused=true; const f=el.querySelector('[autofocus]')||el.querySelector(FOCUSABLE); if(f) setTimeout(()=>f.focus(),30); } }
document.addEventListener('keydown', ev => { const top=PO.ui.sheets.length; if(!top) return; const el=$(top===1?'#sheet':'#sheet2'); if(ev.key==='Escape'){ ev.preventDefault(); PO.closeSheet(); return; } if(ev.key==='Tab'){ const f=[...el.querySelectorAll(FOCUSABLE)].filter(x=>!x.disabled && x.offsetParent!==null); if(!f.length) return; const first=f[0], last=f[f.length-1]; if(ev.shiftKey && document.activeElement===first){ ev.preventDefault(); last.focus(); } else if(!ev.shiftKey && document.activeElement===last){ ev.preventDefault(); first.focus(); } else if(!el.contains(document.activeElement)){ ev.preventDefault(); first.focus(); } } });

/* ---------- toast, notification banner, live region */
let toastTimer, notifTimer; PO.undoGid=null;
PO.toast = (msg, gid) => { const t=$('#toast'); PO.undoGid=gid||null; t.innerHTML=`<span>${esc(msg)}</span>${gid?`<button data-act="undo">${esc(PO.t('undo'))}</button>`:''}`; t.hidden=false; clearTimeout(toastTimer); toastTimer=setTimeout(()=>{ t.hidden=true; PO.undoGid=null; }, 5000); PO.announce(msg); };
PO.notify = (a) => { const n=$('#notif'); const over=a.level>=2; n.innerHTML=`<div class="ic ${over?'over':''}">${over?'!':'80%'}</div><div><b>${esc(a.title)}</b>${esc(a.body||'')}</div>${a.action==='cover'?`<button class="btn sm" data-act="cover" data-env="${esc(a.envId)}">${esc(PO.t('cover'))}</button>`:a.envId?`<button class="btn sm ghost" data-go="envelope" data-p='${esc(JSON.stringify({id:a.envId}))}'>Open</button>`:''}`; n.hidden=false; clearTimeout(notifTimer); notifTimer=setTimeout(()=>{ n.hidden=true; }, 8000); PO.announce(a.title); };
PO.announce = msg => { const l=$('#live'); if(l){ l.textContent=''; setTimeout(()=>{ l.textContent=msg; }, 20); } };
PO.hideBanners = () => { $('#toast').hidden=true; $('#notif').hidden=true; };

/* ---------- generic form engine */
PO.form = (spec) => PO.openSheet('form', spec);
PO.SHEETS.form = { label:'Form', render:(spec)=>{ const v=spec.values||{}; const F=spec.fields.filter(f=>!f.hidden||!f.hidden(v));
  return `<div style="display:flex;justify-content:space-between;align-items:center"><b>${esc(spec.title)}</b><button class="pill" data-act="sheet-close">${esc(PO.t('close'))}</button></div>${spec.intro?`<p class="sub">${esc(spec.intro)}</p>`:''}
  <form data-form="1" novalidate style="margin-top:10px">${F.map(f=>renderField(f,v)).join('')}
  ${spec.extraHtml||''}
  <div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap"><button class="btn" style="flex:1" type="submit">${esc(spec.saveLabel||PO.t('save'))}</button>${(spec.actions||[]).map(a=>`<button type="button" class="btn sm ghost" data-act="form-action" data-k="${esc(a.k)}">${esc(a.label)}</button>`).join('')}${spec.onDelete?`<button type="button" class="btn sm danger" data-act="form-delete">${esc(spec.deleteLabel||PO.t('delete'))}</button>`:''}</div>
  ${spec.footer?`<div class="sub" style="text-align:center;margin-top:8px">${esc(spec.footer)}</div>`:''}</form>`; },
  after:(spec)=>{ const el=$(PO.ui.sheets[PO.ui.sheets.length-1]&&PO.ui.sheets[PO.ui.sheets.length-1].data===spec && PO.ui.sheets.length===2 ? '#sheet2':'#sheet'); const form=el.querySelector('form[data-form]'); if(!form) return;
    form.addEventListener('submit', ev=>{ ev.preventDefault(); const {values, errors}=readForm(spec, form); if(Object.keys(errors).length){ showErrors(form, errors); const first=form.querySelector('.field.invalid input,.field.invalid select,.field.invalid textarea'); if(first) first.focus(); PO.announce(Object.values(errors)[0]); return; } const r=spec.onSave(values); if(r!==false) PO.closeSheet(); });
    form.addEventListener('input', ev=>{ const f=ev.target.closest('.field'); if(f) f.classList.remove('invalid'); if(ev.target.dataset.money!=null){ const cur=ev.target.dataset.cur; const v=PO.evalAmount(ev.target.value); const hint=f.querySelector('.calc'); if(hint) hint.textContent = ev.target.value && /[+\-*\/×÷%()]/.test(ev.target.value.slice(1)) && isFinite(v) ? `= ${PO.fmt(PO.toMinor(v,cur),cur,{force:true})}` : ''; } if(spec.onInput) spec.onInput(ev, form); });
    form.addEventListener('change', ev=>{ if(spec.onChange) spec.onChange(ev, form, readForm(spec, form).values); });
    form.addEventListener('click', ev=>{ const b=ev.target.closest('[data-chip]'); if(b){ ev.preventDefault(); const multi=b.dataset.multi==='1'; if(multi){ b.setAttribute('aria-pressed', b.getAttribute('aria-pressed')!=='true'); } else { b.parentElement.querySelectorAll('[data-chip]').forEach(x=>x.setAttribute('aria-pressed','false')); b.setAttribute('aria-pressed','true'); } if(spec.onChange) spec.onChange(ev, form, readForm(spec, form).values); return; } const sw=ev.target.closest('[data-switch]'); if(sw){ ev.preventDefault(); sw.setAttribute('aria-checked', sw.getAttribute('aria-checked')!=='true'); if(spec.onChange) spec.onChange(ev, form, readForm(spec, form).values); return; } const act=ev.target.closest('[data-act="form-action"]'); if(act){ ev.preventDefault(); const a=(spec.actions||[]).find(x=>x.k===act.dataset.k); if(a){ const r=a.run(readForm(spec, form).values, form); if(r==='close') PO.closeSheet(); } return; } const del=ev.target.closest('[data-act="form-delete"]'); if(del){ ev.preventDefault(); PO.closeSheet(); spec.onDelete(); } });
    form.addEventListener('change', ev=>{ if(ev.target.type==='file'){ const files=[...ev.target.files]; const list=form.querySelector('[data-attach-list]'); files.forEach(file=>{ if(!file.type.startsWith('image/')){ addAttach(list,{name:file.name,type:file.type}); return; } const img=new Image(); const url=URL.createObjectURL(file); img.onload=()=>{ const c=document.createElement('canvas'); const r=Math.min(1, 320/Math.max(img.width,img.height)); c.width=img.width*r; c.height=img.height*r; c.getContext('2d').drawImage(img,0,0,c.width,c.height); addAttach(list,{name:file.name,type:'image/jpeg',data:c.toDataURL('image/jpeg',0.7)}); URL.revokeObjectURL(url); }; img.src=url; }); } });
    if(spec.afterRender) spec.afterRender(form); } };
function addAttach(list, a){ if(!list) return; const id=PO.uid('at'); const d=document.createElement('span'); d.className='chip small'; d.dataset.attach=JSON.stringify({id,...a}); d.innerHTML=`${a.data?`<img src="${a.data}" alt="" style="height:18px;vertical-align:middle;border-radius:3px;margin-inline-end:4px">`:'📄 '}${esc(a.name)} <button type="button" aria-label="Remove" data-rm-attach="1">×</button>`; d.querySelector('[data-rm-attach]').onclick=()=>d.remove(); list.appendChild(d); }
function renderField(f, v){ const val = v[f.k]; const id=`f-${f.k}`; const req=f.required?' <span aria-hidden="true">*</span>':''; const hint=f.hint?`<div class="hint">${esc(f.hint)}</div>`:''; const wrap=(inner)=>`<div class="field" data-field="${esc(f.k)}"><label for="${id}">${esc(f.label)}${req}</label>${inner}${hint}<div class="err-msg" role="alert"></div></div>`;
  switch(f.type){
    case 'money': { const cur=f.cur||PO.cur(); const shown = val!=null && val!=='' ? new Intl.NumberFormat(PO.numLocale(),{minimumFractionDigits:0,maximumFractionDigits:PO.dec(cur),useGrouping:false}).format(PO.toMajor(val,cur)) : ''; return wrap(`<div style="display:flex;gap:8px;align-items:center"><span class="sub" style="min-width:28px">${esc(PO.sym(cur))}</span><input id="${id}" name="${esc(f.k)}" inputmode="decimal" autocomplete="off" data-money="1" data-cur="${esc(cur)}" value="${esc(shown)}" placeholder="0${PO.decSep()}00 ${f.calc!==false?'or 120+80':''}" ${f.autofocus?'autofocus':''}><span class="sub calc" style="min-width:60px"></span></div>`); }
    case 'select': return wrap(`<select id="${id}" name="${esc(f.k)}">${(f.options||[]).map(o=>`<option value="${esc(o.v)}" ${String(o.v)===String(val)?'selected':''} ${o.disabled?'disabled':''}>${esc(o.l)}</option>`).join('')}</select>`);
    case 'chips': return wrap(`<div class="chips" id="${id}" role="group">${(f.options||[]).map(o=>`<button type="button" class="chip small" data-chip="${esc(o.v)}" data-multi="${f.multi?1:0}" aria-pressed="${f.multi?(Array.isArray(val)&&val.includes(o.v)):String(o.v)===String(val)}">${esc(o.l)}</button>`).join('')}</div>`);
    case 'toggle': return `<div class="field" data-field="${esc(f.k)}"><div class="row" style="border-top:0;padding:4px 0"><div><div class="t">${esc(f.label)}</div>${f.hint?`<div class="m">${esc(f.hint)}</div>`:''}</div><button type="button" id="${id}" class="sw" role="switch" aria-checked="${!!val}" data-switch="${esc(f.k)}" aria-label="${esc(f.label)}"></button></div><div class="err-msg" role="alert"></div></div>`;
    case 'date': return wrap(`<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center"><input id="${id}" name="${esc(f.k)}" type="date" value="${esc(val||PO.today())}" style="flex:1;min-width:150px"><button type="button" class="chip small" data-setdate="${PO.today()}">${esc(PO.t('today'))}</button><button type="button" class="chip small" data-setdate="${PO.addDays(PO.today(),-1)}">${esc(PO.t('yesterday'))}</button></div>`);
    case 'time': return wrap(`<input id="${id}" name="${esc(f.k)}" type="time" value="${esc(val||'')}">`);
    case 'textarea': return wrap(`<textarea id="${id}" name="${esc(f.k)}" rows="${f.rows||3}" class="${f.code?'code':''}" placeholder="${esc(f.placeholder||'')}">${esc(val||'')}</textarea>`);
    case 'number': return wrap(`<input id="${id}" name="${esc(f.k)}" type="number" inputmode="decimal" step="${f.step||'any'}" min="${f.min!=null?f.min:''}" max="${f.max!=null?f.max:''}" value="${esc(val==null?'':val)}">`);
    case 'file': return wrap(`<input id="${id}" name="${esc(f.k)}" type="file" accept="image/*,application/pdf" multiple capture="environment"><div class="chips" data-attach-list style="margin-top:6px">${(val||[]).map(a=>`<span class="chip small" data-attach='${esc(JSON.stringify(a))}'>${a.data?`<img src="${a.data}" alt="" style="height:18px;vertical-align:middle;border-radius:3px;margin-inline-end:4px">`:'📄 '}${esc(a.name)} <button type="button" aria-label="Remove" onclick="this.parentElement.remove()">×</button></span>`).join('')}</div>`);
    case 'readonly': return wrap(`<div class="inp" style="background:var(--sunk)">${esc(val||'')}</div>`);
    case 'html': return `<div class="field" data-field="${esc(f.k)}">${f.html(v)}</div>`;
    case 'password': return wrap(`<input id="${id}" name="${esc(f.k)}" type="password" inputmode="numeric" autocomplete="off" value="" ${f.autofocus?'autofocus':''}>`);
    default: return wrap(`<input id="${id}" name="${esc(f.k)}" type="text" value="${esc(val==null?'':val)}" placeholder="${esc(f.placeholder||'')}" list="${f.datalist?id+'-dl':''}" autocomplete="off" ${f.autofocus?'autofocus':''}>${f.datalist?`<datalist id="${id}-dl">${f.datalist.map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`:''}`);
  } }
document.addEventListener('click', ev=>{ const b=ev.target.closest('[data-setdate]'); if(b){ const inp=b.parentElement.querySelector('input[type=date]'); if(inp){ inp.value=b.dataset.setdate; inp.dispatchEvent(new Event('change',{bubbles:true})); } } });
function readForm(spec, form){ const values={}, errors={}; spec.fields.forEach(f=>{ if(f.hidden && f.hidden(spec.values||{})) return; const el=form.querySelector(`[data-field="${CSS.escape(f.k)}"]`); if(!el) return;
  switch(f.type){
    case 'money': { const inp=el.querySelector('input'); const raw=inp.value.trim(); if(!raw){ if(f.required) errors[f.k]='Required'; values[f.k]=null; break; } const major=PO.evalAmount(raw); const err=PO.validateAmount(major, inp.dataset.cur); if(err) errors[f.k]=err; else values[f.k]=PO.toMinor(major, inp.dataset.cur); break; }
    case 'chips': { const on=[...el.querySelectorAll('[data-chip][aria-pressed="true"]')].map(x=>x.dataset.chip); values[f.k]=f.multi?on:(on[0]||null); if(f.required && !on.length) errors[f.k]='Required'; break; }
    case 'toggle': values[f.k]=el.querySelector('[data-switch]').getAttribute('aria-checked')==='true'; break;
    case 'file': values[f.k]=[...el.querySelectorAll('[data-attach]')].map(x=>JSON.parse(x.dataset.attach)); break;
    case 'html': case 'readonly': break;
    case 'number': { const v=el.querySelector('input').value; values[f.k]=v===''?null:Number(v); if(f.required&&v==='') errors[f.k]='Required'; if(v!==''&&f.min!=null&&Number(v)<f.min) errors[f.k]=`Minimum ${f.min}`; break; }
    default: { const inp=el.querySelector('input,select,textarea'); const v=inp?inp.value:''; values[f.k]=v; if(f.required && !String(v).trim()) errors[f.k]='Required'; if(f.validate){ const e=f.validate(v, values); if(e) errors[f.k]=e; } }
  } });
  if(spec.validate){ const e=spec.validate(values); if(e) Object.assign(errors, e); } return {values, errors}; }
function showErrors(form, errors){ form.querySelectorAll('.field').forEach(f=>{ const k=f.dataset.field; const msg=errors[k]; f.classList.toggle('invalid', !!msg); const em=f.querySelector('.err-msg'); if(em) em.textContent=msg||''; }); if(errors._form){ let g=form.querySelector('.form-err'); if(!g){ g=document.createElement('div'); g.className='card err form-err'; form.prepend(g); } g.textContent=errors._form; } }
PO.confirmSheet = (title, body, onYes, yesLabel='Confirm', typed) => PO.openSheet('confirm', {title, body, onYes, yesLabel, typed});
PO.SHEETS.confirm = { label:'Confirm', render:d=>`<b>${esc(d.title)}</b><p class="sub">${esc(d.body)}</p>${d.typed?`<div class="field"><label for="typed">Type <b>${esc(d.typed)}</b> to confirm</label><input id="typed" autofocus autocomplete="off"></div>`:''}<div style="display:flex;gap:8px"><button class="btn danger" data-act="confirm-yes" style="flex:1">${esc(d.yesLabel)}</button><button class="btn ghost sm" data-act="sheet-close">${esc(PO.t('cancel'))}</button></div>` };
PO.ACT['confirm-yes'] = () => { const s=PO.ui.sheets[PO.ui.sheets.length-1]; if(!s) return; if(s.data.typed){ const v=($('#typed')||{}).value||''; if(v.trim()!==s.data.typed){ PO.toast(`Type ${s.data.typed} exactly to confirm`); return; } } PO.closeSheet(); s.data.onYes(); };
PO.ACT['sheet-close'] = () => PO.closeSheet();
PO.ACT['undo'] = () => { if(PO.undoGid){ PO.undoGroup(PO.undoGid); PO.undoGid=null; } $('#toast').hidden=true; PO.render(); PO.toast('Undone'); };

/* ---------- lock screen */
PO.showLock = (mode) => { PO.ui.locked=true; const L=$('#lockScreen'); L.hidden=false; L.innerHTML=`<div class="avatar" style="width:56px;height:56px;font-size:22px;margin-bottom:12px">P</div><h2 style="font-size:20px">${esc(PO.BRAND)} ${esc(PO.state?PO.t('locked'):'is locked')}</h2><p class="sub">${mode==='enc'?'Enter your PIN to decrypt your data on this device.':'Enter your PIN.'}</p><input id="lockPin" class="inp" type="password" inputmode="numeric" maxlength="8" autocomplete="off" aria-label="PIN" style="max-width:200px;text-align:center;font-size:22px;letter-spacing:.3em"><div style="height:10px"></div><button class="btn" style="max-width:200px" id="lockGo">${esc(PO.state?PO.t('unlock'):'Unlock')}</button><button class="chip small" id="lockBio" style="margin-top:10px">Use biometrics (simulated)</button><div class="sub" id="lockMsg" style="margin-top:10px;min-height:18px"></div><p class="sub" style="margin-top:20px">Forgot the PIN? Use your recovery kit from Settings › Security, or reset the demo above the frame.</p>`;
  const go=async ()=>{ const pin=$('#lockPin').value; $('#lockMsg').textContent='Checking…'; const r = mode==='enc' ? await PO.unlock(pin) : (pin===PO.ui.sessionPin ? true : false); if(r){ PO.ui.locked=false; L.hidden=true; if(mode==='enc'){ PO.ui.sessionPin=pin; PO.afterLoad(); const h=decodeHash(); PO.go(h&&PO.SCREENS[h.screen]?h.screen:'home', (h&&h.params)||{}, {replace:true}); setTimeout(()=>{ try{ const fresh=PO.fireAlerts(); if(fresh.length) PO.notify(fresh[0]); }catch(e){} }, 1200); } else PO.render(); PO.toast(r==='duress'?'Opened':'Unlocked'); } else { $('#lockMsg').textContent='That PIN did not open any book. Try again.'; $('#lockPin').value=''; $('#lockPin').focus(); } };
  $('#lockGo').onclick=go; $('#lockPin').onkeydown=e=>{ if(e.key==='Enter') go(); }; $('#lockBio').onclick=()=>{ if(mode==='enc'){ $('#lockMsg').textContent='Biometrics cannot derive the encryption key without a stored PIN on this prototype. Enter the PIN once.'; return; } PO.ui.locked=false; L.hidden=true; PO.render(); PO.toast('Unlocked with biometrics'); }; setTimeout(()=>$('#lockPin').focus(),50); };
PO.lockNow = () => { if(!PO.state||!PO.state.settings.lockPin) return; PO.closeAllSheets(); PO.showLock('session'); };
['click','keydown','touchstart'].forEach(e=>document.addEventListener(e,()=>{ PO.ui.lastActive=Date.now(); }, {passive:true}));
setInterval(()=>{ if(PO.state && PO.state.settings.lockPin && !PO.ui.locked && PO.state.settings.autoLock>0 && Date.now()-PO.ui.lastActive > PO.state.settings.autoLock*1000) PO.lockNow(); }, 5000);

/* ---------- global click dispatch */
document.addEventListener('click', ev=>{ const b=ev.target.closest('[data-go],[data-act],[data-nav],[data-gap],[data-sheet]'); if(!b) return; if(b.closest('form[data-form]') && (b.dataset.act==='form-action'||b.dataset.act==='form-delete')) return;
  if(b.dataset.gap!=null){ const p=JSON.parse(b.dataset.p||'{}'); if(PO.SHEETS[b.dataset.gap]&&!PO.SCREENS[b.dataset.gap]){ if(PO.ui.screen==='onboarding') PO.go('home'); PO.openSheet(b.dataset.gap, p); } else PO.go(b.dataset.gap, p); return; }
  if(b.dataset.nav){ const k=b.dataset.nav; if(PO.SCREENS[k]) PO.go(k, {}); else { if(PO.ui.screen==='onboarding') PO.go('home'); PO.openSheet(k, {}); } return; }
  if(b.dataset.sheet){ PO.openSheet(b.dataset.sheet, JSON.parse(b.dataset.p||'{}')); return; }
  if(b.dataset.go){ PO.go(b.dataset.go, JSON.parse(b.dataset.p||'{}')); return; }
  const fn=PO.ACT[b.dataset.act]; if(fn){ ev.preventDefault(); fn(b, ev); } });
document.addEventListener('keydown', ev=>{ if(ev.key==='Enter'||ev.key===' '){ const el=ev.target.closest('[role="button"][data-act],[role="button"][data-go]'); if(el && el.tagName!=='BUTTON'){ ev.preventDefault(); el.click(); } } });
$('#scrim').addEventListener('click', ()=>PO.closeSheet(0)); $('#scrim2').addEventListener('click', ()=>PO.closeSheet(1));
$('#fab').addEventListener('click', ()=>{ if(!PO.can('create')){ PO.toast('Your role in this space cannot add transactions'); return; } PO.openSheet('add', {}); });
let pressTimer; $('#fab').addEventListener('pointerdown', ()=>{ pressTimer=setTimeout(()=>{ PO.openSheet('add',{full:true}); }, 550); }); ['pointerup','pointerleave','pointercancel'].forEach(e=>$('#fab').addEventListener(e, ()=>clearTimeout(pressTimer)));

/* ---------- top controls */
$('#frPhone').onclick=()=>{ PO.ui.tablet=false; $('#phone').classList.remove('tablet'); $('#frPhone').setAttribute('aria-pressed','true'); $('#frTablet').setAttribute('aria-pressed','false'); PO.render(); };
$('#frTablet').onclick=()=>{ PO.ui.tablet=true; $('#phone').classList.add('tablet'); $('#frPhone').setAttribute('aria-pressed','false'); $('#frTablet').setAttribute('aria-pressed','true'); PO.render(); };
$('#pnNotes').onclick=()=>{ $('#notesPane').hidden=false; $('#gapsPane').hidden=true; $('#pnNotes').setAttribute('aria-pressed','true'); $('#pnGaps').setAttribute('aria-pressed','false'); };
$('#pnGaps').onclick=()=>{ $('#notesPane').hidden=true; $('#gapsPane').hidden=false; $('#pnNotes').setAttribute('aria-pressed','false'); $('#pnGaps').setAttribute('aria-pressed','true'); };
$('#resetDemo').onclick=()=>{ PO.wipeAll(); PO._key=null; PO.decoy=false; PO.ui.locked=false; $('#lockScreen').hidden=true; PO.state=PO.seed('IN'); PO.saveNow(); PO.ui.stack=[]; PO.go('onboarding',{},{replace:true}); PO.toast('Demo data reset'); };
(function tick(){ const d=new Date(); $('#clock').textContent=d.getHours()+':'+String(d.getMinutes()).padStart(2,'0'); setTimeout(tick,30000); })();

/* ---------- boot */
PO.afterLoad = () => { PO.fixOccIds(); PO.list('recur').forEach(PO.ensureOcc); PO.ui.sessionPin = PO.ui.sessionPin||null; };
PO.boot = () => { PO.renderGaps(); const raw=PO.loadRaw(); if(raw && raw.enc){ PO.showLock('enc'); return; } if(raw && raw.ent){ PO.state=raw; } else { PO.state=PO.seed('IN'); PO.saveNow(); } PO.afterLoad(); const r=decodeHash(); if(!PO.state.settings.onboarded) PO.go('onboarding',{},{replace:true}); else if(r && PO.SCREENS[r.screen]) PO.go(r.screen, r.params, {replace:true}); else PO.go('home',{},{replace:true}); setTimeout(()=>{ try{ const fresh=PO.fireAlerts(); if(fresh.length) PO.notify(fresh[0]); }catch(e){ console.error(e); } }, 1200); };
window.addEventListener('load', ()=>{ if(PO.SCREENS.home) PO.boot(); });
})(window.PO);
